/* notes.js — notas do formador, uma entrada por slide (chave = id do slide).
   Geradas a partir das notas do PowerPoint; para as alterar, edita o texto aqui.
   O painel abre com a tecla N. */
window.NOTES = {
 "s-abertura": "Sessão 1 da unidade CP 4 (Cidadania e Profissionalidade 4: Processos identitários). 100 minutos.\nPlano: apresentação da unidade e regras do grupo, 15 minutos; o meu nome, 15; o que é identidade, 25; vinte afirmações, 10; análise, 10; partilha, 15; conceitos e bilhete de saída, 10.\nMateriais: folhas com 20 linhas numeradas para a atividade «Eu sou…» (uma por formando).\nCuidado geral: esta unidade toca em identidade, origem, religião, género e orientação sexual. Toda a partilha é voluntária.",
 "s-programa": "DR = Domínio de Referência para a Acção. O referencial define 4 contextos (privado, profissional, institucional, macroestrutural) que, cruzados com o Núcleo Gerador «Identidade e Alteridade», geram os 4 temas do programa. Unidade de Competência 4: Valorizar a diversidade e actuar segundo convicções próprias.",
 "s-dr1": "",
 "s-regras": "Numa unidade sobre identidade, as regras de convivência vêm primeiro. Propõe estas quatro e pede à turma que acrescente uma ou duas. Escreve-as numa folha grande e afixa-a na sala: serve para todas as sessões.\nA quarta regra é importante para a avaliação: qualquer atividade pessoal pode ser feita com um caso fictício, e vale o mesmo.",
 "s-nome": "Volta à sala: cada formando conta, em cerca de um minuto, a história do seu nome. Começa tu, para dar o exemplo e mostrar o tom.\nO nome é a primeira marca de identidade que recebemos dos outros: liga o pessoal (como me chamam) ao social (família, língua, religião, país, época). É uma boa ponte para os conceitos do diapositivo seguinte.\nSe alguém não quiser falar do nome, pode falar de uma alcunha ou dizer só como prefere ser tratado.\n\nOntologia / estatuto ontológico de pessoa.",
 "s-nome-comum": "Começar pela gramática, que todos conhecem: o nome comum aplica-se a qualquer membro de uma classe; o nome próprio escolhe um indivíduo entre muitos (no diagrama, o círculo laranja).\n\nIdeia de John Stuart Mill: os nomes próprios designam sem conotar, isto é, apontam para o indivíduo sem lhe atribuir características. Prova simples: o rio Tejo continuaria a chamar-se Tejo se mudasse de curso; uma Clara pode ser morena.\n\nPergunta à turma: o vosso nome diz alguma coisa sobre vocês? (Ligar à ficha 'A história do meu nome'.)",
 "s-a-quem": "Mostrar primeiro só o título e perguntar: a que animais damos nomes? E a que coisas?\n\nObjeção que a turma pode levantar (e ainda bem): damos nomes a navios, furacões, cidades, e nem todos os animais têm nome. O nome próprio é dado ao que destacamos como indivíduo e com quem temos uma relação. A diferença: às pessoas, o nome é sempre devido, por serem pessoas; aos outros, damo-lo por escolha nossa. Aqui entra a distinção entre pessoa e humano.\n\nDesumanização: em Auschwitz, os prisioneiros tinham um número tatuado no braço e eram chamados por ele. Anonimato: nem sempre é negativo (voto secreto, denúncias protegidas).",
 "s-delimitar": "Ideia de partida: para estudar algo temos de o delimitar. Em física (termodinâmica), escolhe-se um sistema; tudo o resto é a vizinhança; os dois juntos formam o universo. A fronteira separa e liga: é por ela que passam as trocas.\n\nO mesmo em lógica: o gato define-se pela negação do que não é gato. Espinosa escreveu, numa carta (Carta 50), que a determinação é negação; Hegel retomou a fórmula como «toda a determinação é negação».\n\nAplicado à consciência: o eu define-se por oposição ao outro, e ambos formam o universo.\n\nA viragem (caixa em baixo): para Hegel, o «não-eu» inclui coisas (o gato, a pedra) e outras pessoas, e não é a mesma coisa. Se o outro fosse só «não-eu», seria um objeto, e é assim que o desejo o trata. O que torna possível o reconhecimento é o outro ser também um sujeito, que me delimita a mim como eu o delimito a ele. Daqui se passa ao diapositivo seguinte.",
 "s-desejo": "Fenomenologia do Espírito (1807), capítulo IV, §166–175.\n\nPasso 1: quando a consciência se volta para si, só encontra «Eu = Eu», uma certeza vazia (Hegel chama-lhe tautologia sem movimento).\nPasso 2: o desejo tenta dar-lhe conteúdo: nega o objeto (come a maçã, bebe a água) e sente-se certo de si. Mas o objeto desaparece e o desejo volta; a satisfação depende sempre de um novo objeto.\nConclusão: só satisfaz um objeto que permaneça e que se «negue a si próprio» por si mesmo, isto é, outro sujeito.\n\nExemplo para adultos: comprar coisas novas dá uma satisfação que passa depressa; o que nos confirma de forma duradoura é o reconhecimento dos outros (um elogio sincero, ser chamado pelo nome).",
 "s-reconhecer": "§176–184. A satisfação do desejo é, afinal, uma «duplicação» da consciência de si: preciso de outro como eu.\n\nO reconhecimento tem dois movimentos (§179–181): (1) a consciência perde-se, encontra-se no outro como num espelho; (2) regressa a si, e ao fazê-lo devolve o outro a si próprio, deixa-o livre.\n\nLigação ao nome: quando alguém me chama pelo nome, reconhece-me como esta pessoa, não como «um cliente» ou «o 23». Nomear é o primeiro gesto de reconhecimento.\n\nPergunta: lembram-se de uma situação em que se sentiram reconhecidos? E de uma em que se sentiram invisíveis?",
 "s-senhor": "§185–196. «Senhor e servo» traduz Herr e Knecht (há traduções com «escravo»; «servo» está mais perto do alemão).\n\nA luta de vida ou morte é uma alegoria: se um matar o outro, perde quem o podia reconhecer (não se é reconhecido por um cadáver). Por isso um cede e torna-se servo.\n\nO paradoxo: o senhor parece ter ganho, mas é reconhecido por alguém que não reconhece como igual. O servo, pelo trabalho, transforma o mundo e vê-se no que produz.\n\nLigação à unidade (resultado 2, pertença no trabalho): relações de trabalho em que só um lado é reconhecido. Exemplos da turma?",
 "s-mutuo": "§182–184: o reconhecimento é ação dos dois ao mesmo tempo; reconhecem-se como reconhecendo-se mutuamente.\n\nVertical/horizontal: distinção de Heikki Ikäheimo (comentador de Hegel), usada no preprint. Vertical também inclui a relação entre o Estado e os cidadãos: ponte para as sessões sobre políticas públicas.\n\nCuidado de rigor: no capítulo IV, Hegel apresenta o reconhecimento mútuo como o conceito puro, mas a história do capítulo não acaba aí (segue-se o estoicismo, o ceticismo, a consciência infeliz). A frase «só o reconhecimento mútuo funciona» é a leitura do preprint e de muitos comentadores, não um desfecho narrado por Hegel nesse capítulo.\n\nFecho: voltar ao nome e à pergunta da sessão — precisamos dos outros para saber quem somos?",
 "s-idem": "A palavra «identidade» vem do latim idem, «o mesmo». Tem duas faces que parecem opostas: é o que se mantém igual em mim ao longo do tempo (sou a mesma pessoa que era aos 10 anos?) e é o que me distingue dos outros. Ao mesmo tempo, partilho parte da minha identidade com grupos: sou igual a uns e diferente de outros.\nPergunta à turma: em que sou hoje igual ao que era há 20 anos? E em que mudei?",
 "s-teseu": "Divisória da sessão. Escreve o sumário no quadro: «O navio de Teseu: o que é a identidade? O que faz de mim a mesma pessoa ao longo do tempo?»\n\nEste bloco dá para duas sessões de 100 minutos: a primeira até ao diapositivo sobre Locke; a segunda começa na divisória «Phineas Gage».\n\nOs diapositivos têm animações: cada clique faz aparecer o passo seguinte. Ligação: retoma o diapositivo «idem — ser o mesmo».",
 "s-mito": "Banda desenhada em seis vinhetas: a primeira aparece logo; cada clique mostra a seguinte.\n\nConta a história como uma história, sem pressa — com adultos funciona bem pedir a alguém que conheça o mito para o ir contando enquanto as vinhetas aparecem.\n\nNotas para ti:\n• O tributo: Plutarco fala em «de nove em nove anos»; outras versões dizem todos os anos.\n• Depois de sair do Labirinto, Teseu foge com Ariadne, mas abandona-a na ilha de Naxos (podes omitir).\n• A morte de Egeu: em Plutarco, Egeu atira-se de um rochedo; na versão mais divulgada, atira-se ao mar a partir do cabo Súnio, e o mar passa a ter o seu nome.\n• A última vinheta é a ponte: este é o navio cujas tábuas os atenienses foram trocando. O diapositivo seguinte começa aí.\n\nPergunta rápida antes de avançar: que pormenor da história vai interessar à filosofia? (O navio — e a vela que não foi trocada.)",
 "s-navio": "Quatro cliques: a cada clique, três tábuas são trocadas e o contador desce (9 → 6 → 3 → 0). O quinto clique mostra a pergunta.\n\nNão é preciso saber nada sobre Teseu: basta saber que o navio era guardado como um monumento.\n\nPergunta à turma e regista no quadro um «sim» e um «não», com as razões. Respostas típicas: «sim, tem o mesmo nome e a mesma forma» / «não, já não tem nada do original». Pergunta também: em que momento deixou de ser o mesmo? À primeira tábua? À quinta? À última?",
 "s-hobbes": "Clique 1: navio A. Clique 2: navio B. Clique 3: votação.\n\nVotação de braço no ar. Se a maioria escolheu A: então a matéria não conta? Se escolheu B: então o navio desapareceu do porto sem ninguém dar por isso? Quem diz «os dois» tem de explicar como pode haver dois navios de Teseu ao mesmo tempo.\n\nObjetivo: mostrar que «ser o mesmo» pode querer dizer coisas diferentes — a mesma matéria, a mesma forma, uma história contínua.",
 "s-igual": "Clique 1: as notas (iguais, mas duas). Clique 2: Batman e Bruce Wayne (um só, dois nomes). Clique 3: pergunta.\n\nPergunta à turma: «Batman é idêntico a Bruce Wayne?» Sim, no sentido forte: não são duas coisas que partilham tudo, são uma só. Os gémeos verdadeiros e as notas de 20 € são idênticos só no sentido fraco: são iguais, mas são dois.\n\nO problema do navio é sobre a identidade numérica: o navio restaurado é o mesmo navio, ou só um navio igual ao de Teseu?\n\nGuarda a palavra fungibilidade: as tábuas são fungíveis (qualquer uma serve). Voltamos a ela no fim, com Levinas: as pessoas não são.",
 "s-essencial": "Clique 1: exemplos de propriedades acidentais. Clique 2: o núcleo essencial do navio. Clique 3: os existencialistas. Clique 4: pergunta.\n\nRigor: os existencialistas não negam que os objetos tenham essência — o exemplo de Sartre é precisamente o corta-papel, que foi pensado (essência) antes de ser feito (existência). O que negam é que exista uma natureza humana fixada à partida: o ser humano define-se pelo que faz de si.\n\nLigação com a CP 8 (projetos pessoais): se não há essência dada, a identidade é também um projeto.",
 "s-corpo": "Quatro cliques, um por marcador; o quinto mostra a pergunta.\n\nRigor: é um mito que «todas as células do corpo se renovam a cada sete anos». Algumas renovam-se depressa (pele, sangue, revestimento do intestino); o esqueleto é remodelado aos poucos; a maior parte dos neurónios do córtex tem a idade da pessoa (mostrado com datação por carbono-14).\n\nPergunta: se o cérebro é a parte que menos muda, será ele o «verdadeiro eu»? É a ponte para o cientista louco e, mais tarde, para Phineas Gage.",
 "s-cientista": "Clique 1: a troca. Clique 2: as mentes trocadas. Clique 3: a escolha. Clique 4: pergunta.\n\nConta a história como no teu diapositivo: um cientista vai transferir todo o teu conteúdo mental (crenças, memórias, personalidade) para o corpo de outra pessoa, e o dela para o teu. Depois, um dos corpos recebe um milhão de euros e o outro é torturado — e és tu quem decide qual.\n\nQuase toda a gente quer o milhão para o corpo B (para onde vai a sua mente): isso sugere que somos a nossa psicologia, não o nosso corpo. Williams mostra depois que, contada de outra maneira («amanhã vais ser torturado, mas antes vais esquecer tudo»), a intuição muda — e já ninguém se sente seguro. Pergunta: e se fosse só metade das memórias?",
 "s-locke": "A cadeia: cada «eu» lembra-se do anterior, e é essa cadeia que faz de mim a mesma pessoa. Quatro cliques para os quatro problemas; o quinto mostra a pergunta, que serve de ponte para Phineas Gage.\n\n1. Dormir: a consciência interrompe-se todas as noites — acordo outra pessoa?\n2. Ninguém se lembra de ter nascido: perdemos os primeiros anos.\n3. Amnésia e demência: se a identidade é memória, quem perde a memória muda de identidade. Pergunta delicada — alguém pode ter um familiar com demência.\n4. Falsas memórias: a memória reconstrói, não grava.",
 "s-gage": "Divisória da segunda sessão. Escreve o sumário no quadro: «O caso de Phineas Gage: o cérebro e a identidade pessoal. A lobotomia. Identidade e alteridade: Ricoeur e Levinas.»\n\nRecapitula em dois minutos: navio de Teseu, teoria do corpo, teoria da memória. Pergunta deixada no fim da aula anterior: e quando a memória fica, mas o carácter muda?",
 "s-gage-acidente": "Clique 1: a explosão — a barra atravessa a cabeça (animação de baixo para cima). Clique 2: sobrevive. Clique 3: pergunta.\n\nFactos: a barra tinha 1,09 m (3 pés e 7 polegadas), 3,2 cm de diâmetro e cerca de 6 kg; afunilava numa ponta. Entrou por baixo do osso da maçã do rosto esquerda, passou por trás da órbita do olho e saiu pelo topo do crânio. Gage foi levado de carroça para a vila e subiu as escadas do hotel pelo seu pé.\n\nNão mostres fotografias do crânio se a turma for sensível; a ilustração chega.",
 "s-gage-cerebro": "Clique 1: a zona destruída e o trajeto da barra. Clique 2: o que ficou. Clique 3: o que mudou. Clique 4: o estudo de 2012.\n\nNão houve autópsia nem o cérebro foi preservado — só o crânio, hoje no Museu Anatómico Warren, em Harvard. As reconstruções fazem-se a partir do crânio. Damásio e colegas (1994) defenderam lesão nos dois lobos frontais; os estudos mais recentes (2004, 2012) apontam para lesão direta só no lobo frontal esquerdo, mas com ligações cortadas que afetam os dois hemisférios.\n\nIdeia-chave para a turma: Gage não perdeu a memória nem a capacidade de falar. O que mudou foi a forma de se relacionar com os outros e de se controlar.",
  "s-sapolsky": "Recapitulação da aula anterior. Clique 1: a linha do tempo. Clique 2: menos genes, mais experiência. Clique 3: as regras aprendem-se no contexto sociocultural. Clique 4: o que Gage perdeu. Clique 5: pergunta.\n\nSapolsky (Behave, cap. 2 e 7): por ser a última região a amadurecer (meados dos 20 anos), o córtex frontal é, por definição, a menos limitada pelos genes e a mais esculpida pela experiência; e é ele que nos faz fazer a coisa mais difícil quando é a certa. Rigor: os «25 anos» são uma aproximação; o amadurecimento é gradual e varia de pessoa para pessoa. As barras do gráfico são esquemáticas, não medidas.\n\nA pergunta liga à «reviravolta» do slide seguinte (Gage cocheiro no Chile, Macmillan).",
 "s-gage-depois": "Clique 1: o «depois». Cliques 2 a 4: as três teorias. Clique 5: a reviravolta. Clique 6: pergunta.\n\nHarlow (1868) escreveu que a mudança foi tão marcada que os amigos e conhecidos diziam que ele «já não era o Gage».\n\nCuidado com o mito: muitos manuais exageram as mudanças. Malcolm Macmillan mostrou que Gage trabalhou anos como cocheiro no Chile, o que exige rotina, autocontrolo e trato com passageiros — sinal de uma possível «recuperação social». Morreu em São Francisco em 1860, após crises epiléticas, cerca de 11 anos e meio depois do acidente.\n\nDebate: pelas teorias do corpo e da memória, Gage continuou a ser o mesmo. Mas para quem convivia com ele, não. Quem tem razão? E se a mudança fosse para melhor — alguém que deixa de ser violento — diríamos que é outra pessoa?",
 "s-lobotomia": "Clique 1: 1935 (aparecem os cortes no lobo frontal). Clique 2: Nobel e Freeman. Clique 3: declínio. Clique 4: citação. Clique 5: pergunta.\n\nLigação com Gage: Gage mostrou, por acidente, que o lobo frontal tem a ver com a personalidade. A leucotomia faz de propósito algo parecido: corta ligações do lobo frontal para acalmar doentes graves.\n\nO Nobel de Moniz (1949, «pela descoberta do valor terapêutico da leucotomia em certas psicoses») continua polémico; houve pedidos para que fosse retirado. Freeman fazia a lobotomia transorbital com um instrumento parecido com um furador de gelo, muitas vezes sem anestesia geral e com consentimento duvidoso.\n\nLigação ao DR2 (códigos deontológicos): consentimento informado. E a Levinas: tratar o outro como uma coisa a corrigir é reduzir o Outro ao Mesmo.",
 "s-contrato": "Clique 1: o patrão. Clique 2: conclusão. Clique 3: pergunta.\n\nO exemplo é absurdo de propósito: ninguém aceitaria esta desculpa. Mas, se levarmos Heraclito ou Leibniz à letra, o patrão teria razão!\n\nA sociedade precisa de que sejamos os mesmos: esperamos que as pessoas cumpram promessas, paguem dívidas, respondam pelos seus atos. A pergunta prepara Ricoeur: talvez a identidade de uma pessoa não seja só aquilo que permanece igual, mas a capacidade de manter a palavra.",
 "s-ricoeur": "Clique 1: idem. Clique 2: ipse. Clique 3: a promessa. Clique 4: conclusão e pergunta.\n\nRicoeur dá-nos o vocabulário que faltava. «Idem» é a palavra latina que já vimos (o mesmo); «ipse» também é latim e quer dizer «ele próprio», «si mesmo».\n\nO navio só tem identidade idem. Uma pessoa tem as duas: posso mudar de corpo, de gostos, até de carácter (Gage!) e, mesmo assim, ser «eu» quando cumpro o que prometi. Responde ao patrão do diapositivo anterior: sou eu quem assinou, porque sou eu quem responde por essa assinatura.\n\nO título do livro diz tudo: o «si mesmo» compreende-se através do outro. É a ponte para Levinas.",
 "s-levinas": "Clique 1: o Mesmo absorve (conhecer, classificar, possuir). Clique 2: o Outro fica de fora. Cliques 3 e 4: texto. Clique 5: pergunta.\n\nLiga à palavra «idem»: o Mesmo é tudo o que eu consigo trazer para dentro do meu mundo. Funciona bem com coisas (como o navio, ou um cérebro que se pode cortar e «corrigir»).\n\nCom pessoas, há um limite: o outro nunca é totalmente compreendido. Quando acho que já sei tudo sobre alguém, transformo-o numa coisa. Isto é a alteridade.\n\nExemplos do dia a dia: rótulos («ele é assim», «os de lá são todos iguais») — ligação com os estereótipos trabalhados na CP 3.",
 "s-rosto": "Um clique por linha; o quarto mostra a pergunta.\n\n«Rosto» em Levinas não é a cara no sentido físico — por isso a frase sobre a cor dos olhos. É a presença de alguém que me olha e que pode ser ferido.\n\nA frase completa: «O \"Não matarás\" é a primeira palavra do rosto.» Não é uma ordem escrita num código: é o que sentimos quando estamos frente a frente com alguém frágil.\n\nLigação ao DR1.5 (empatia, princípios de conduta) e ao DR2 (códigos deontológicos): para Levinas, os códigos vêm depois; primeiro está a responsabilidade perante um rosto concreto. Exemplos: a facilidade com que se insulta alguém nas redes sociais, sem rosto.",
 "s-modelos": "Clique 1: Hegel. Clique 2: Levinas. Clique 3: pergunta.\n\nRetoma os diapositivos sobre Hegel (senhor e servo; só o reconhecimento mútuo funciona). Em Hegel, a relação é uma troca entre iguais.\n\nLevinas muda o desenho: a responsabilidade pelo outro não espera troca. O «Tu» aparece mais acima de propósito — Levinas diz que o outro me chega «de cima», como alguém que me pede algo.\n\nDebate: os dois modelos excluem-se? Provavelmente não: na vida profissional (DR2) precisamos de reciprocidade — contratos, direitos; mas há momentos (cuidar de um doente, de uma criança, de um colega em crise) em que agimos sem esperar nada.",
 "s-tabuas": "Um clique por cartão; depois a citação; depois a pergunta.\n\nFecho: as tábuas do navio são fungíveis — qualquer uma serve, como as notas de 20 €. Uma pessoa, diante de alguém que precisa dela, não é: ninguém pode responder no seu lugar. Para Levinas, é aí que está a identidade mais profunda.\n\nBilhete de saída: cada formando escreve, num papel, uma frase a responder à pergunta. As frases podem alimentar o glossário pessoal e a atividade das vinte afirmações.\n\nNota: a citação vem de uma entrevista de Levinas a François Poirié; «ele» refere-se ao outro, a outrem.",
 "s-pessoal-social": "A distinção vem da psicologia social. Henri Tajfel e John Turner (teoria da identidade social, 1979) mostraram que uma parte importante da forma como nos vemos vem dos grupos a que pertencemos, e que tendemos a favorecer o nosso grupo face aos outros. É a base para as sessões sobre preconceito e discriminação (sessões 5 a 8).\nPede exemplos à turma para cada coluna antes de mostrares os do diapositivo.",
 "s-papeis": "Cada pessoa desempenha vários papéis sociais ao mesmo tempo, com expectativas diferentes: no trabalho espera-se uma coisa, em casa outra. Às vezes os papéis entram em conflito (ser trabalhador e ser pai ou mãe com um filho doente).\nMini-atividade de 3 minutos: cada formando desenha o seu próprio diagrama de papéis numa folha. Guarda-o: vai ser útil na sessão 2 (identidade e alteridade) e na unidade CP 8.\nAmin Maalouf, em As Identidades Assassinas (1998), defende que a identidade de cada pessoa é feita de muitas pertenças, e que reduzir alguém a uma só (a religião, a origem) é o primeiro passo para a intolerância.",
 "s-espelho": "Charles Horton Cooley (1902) chamou-lhe o «eu-espelho» (looking-glass self): imaginamos como os outros nos veem, imaginamos o que pensam disso, e isso muda o que sentimos sobre nós. George Herbert Mead (1934) acrescentou que nos tornamos pessoas na interação com os outros.\nLiga ao que os formandos vivem: um elogio de um chefe, um rótulo na escola («não tens jeito para…»), a forma como os outros reagem ao nosso sotaque ou à nossa origem. Este último ponto prepara as sessões sobre discriminação.",
 "s-vinte": "O teste das vinte afirmações foi criado por Manford Kuhn e Thomas McPartland (1954) para estudar o autoconceito. Aqui não é um teste: é um exercício de reflexão, sem respostas certas, e ninguém lê a folha de ninguém sem autorização.\nDistribui folhas com 20 linhas numeradas. Dá 7 a 8 minutos e insiste: escrever depressa, sem pensar muito, pela ordem em que as ideias aparecem. A ordem importa para a análise seguinte.",
 "s-analise": "Cada formando classifica as suas afirmações nas quatro categorias (uma afirmação pode caber em mais de uma) e conta quantas tem em cada. Trabalho individual; a partilha vem a seguir.\nNa investigação com este teste, é comum que as primeiras respostas sejam papéis e grupos (identidade social) e as seguintes traços pessoais. Não apresentes isto como regra: deixa que os formandos vejam o que acontece nas suas próprias folhas.",
 "s-glossario": "Os conceitos para o caderno ou para o glossário da turma. «Alteridade» é o tema da sessão 2: deixa-o aqui como antecipação.",
 "s-quiz1": "5 minutos. Projetar e responder em grupo: os formandos dizem a resposta, o formador clica. Cada pergunta tem uma só tentativa e mostra a explicação. O botão «Tentar outra vez» limpa as respostas.",
 "s-quiz2": "5 minutos. Revisão do bloco do navio de Teseu: identidade qualitativa e numérica, essencial e acidental, Heraclito, teoria do corpo, Locke e os existencialistas.",
 "s-pesquisa-nobel": "5 minutos, em pares. Resposta (página oficial do Prémio Nobel): o prémio de 1949 foi dividido em partes iguais entre Walter Rudolf Hess, «pela descoberta da organização funcional do diencéfalo como coordenador das atividades dos órgãos internos», e Egas Moniz, «pela descoberta do valor terapêutico da leucotomia em certas psicoses».\nLigação: o Nobel de Moniz continua polémico (ver notas do diapositivo anterior).",
  "s-gage-programa": "Fecho da parte do cérebro e ligação ao programa. Clique 1: DR1 (identidade e princípios de conduta). Clique 2: DR2 (deontologia: Kant e Mill; a lobotomia e o consentimento). Clique 3: pergunta para discutir em dois minutos.\n\nA seguir: o jogo do cérebro (projetado ou no telemóvel) e depois Ricoeur e Levinas.",
  "s-jogo-cerebro": "Jogo sobre a primeira parte da aula: lobos, neurónios e glia, tálamo, lobotomia, o estudo do dilema da ponte e Sapolsky. Projetar e pedir respostas de braço no ar (1 a 3) ou usar o slide seguinte para jogar no telemóvel.",
  "s-tel-cerebro": "Versão no telemóvel do jogo do cérebro (a=cerebro): jogo, mais 3 respostas escritas (o dilema do elétrico, Gage e a identidade, onde aprenderam as regras de conduta). As respostas vão para a folha «Avaliação contínua».",
 "s-quiz3": "5 minutos. Revisão do bloco Phineas Gage, lobotomia, Ricoeur e Levinas.",
 "s-classificar": "5 minutos. Os exemplos são os do diapositivo anterior. Projetar e responder em grupo.\nA pergunta final é de propósito: «sou crente» é uma convicção pessoal e, ao mesmo tempo, uma pertença a um grupo religioso. As duas colunas não são caixas estanques.",
 "s-jogo1": "Jogo para a turma: projetar, ler a pergunta em voz alta e pedir respostas de braço no ar (ou com os dedos, 1 a 4) antes de clicar. O formador clica na resposta mais votada, ou usa as teclas 1 a 4; Enter passa à seguinte. O botão do altifalante liga e desliga o som. Depois de cada resposta, aproveitar a explicação para uma pergunta de seguimento.",
 "s-jogo2": "Jogo para a turma: projetar, ler a pergunta em voz alta e pedir respostas de braço no ar (ou com os dedos, 1 a 3) antes de clicar. Teclas 1 a 3 escolhem; Enter passa à seguinte. Perguntas atualizadas para o bloco reformulado (fungível, Nokia, «Fale-me de si»).",
 "s-jogo3": "Jogo para a turma: projetar, ler a pergunta em voz alta e pedir respostas de braço no ar (ou com os dedos, 1 a 3) antes de clicar. Teclas 1 a 3 escolhem; Enter passa à seguinte. Perguntas atualizadas (promessas, email, atendimento).",
 "s-jogo4": "Jogo para a turma: projetar, ler a pergunta em voz alta e pedir respostas de braço no ar (ou com os dedos, 1 a 4) antes de clicar. O formador clica na resposta mais votada, ou usa as teclas 1 a 4; Enter passa à seguinte. O botão do altifalante liga e desliga o som. Depois de cada resposta, aproveitar a explicação para uma pergunta de seguimento.",
 "s-teseu-hoje": "Bloco DR1.2 reformulado: menos exposição, mais exercícios. Cabe em duas sessões de 100 minutos.\nSessão A: mito e navio, 10 min; Hobbes (votação), 5; navios da vida real (folha), 15; igual ou o mesmo + és fungível? (folha), 20; duas respostas extremas (votação), 10; essencial ou acidental (jogo), 10; corpo e cientista louco (votação), 20; Locke, 10.\nSessão B: o meu navio (folha), 15; «Fale-me de si» (folha), 20; entrevista em pares, 25; pesquisa Nokia (telemóvel), 10; para que serve, 5; jogo, 10; bilhete de saída, 5.\nEste slide é a promessa da aula: diz já para que serve. Volta a ele no fim.",
 "s-navios-reais": "Folha em branco, a pares. Abre os cartões um a um (clicar) e lê em voz alta.\nCada formando faz duas colunas, «Mudou» / «Ficou», para três casos; o último é sempre «tu, há 15 anos».\nPartilha rápida: o que fica costuma ser o nome, o número, o sítio, a função, as relações. Guarda esta ideia: é a «quilha» de que falamos na sessão B.\nNokia: fundada em 1865 por Fredrik Idestam como fábrica de pasta de madeira (Tampere, Finlândia); fusão em 1967 com as fábricas de borracha e de cabos; nos anos 90 concentrou-se nas telecomunicações (Wikipedia, «History of Nokia»; finland.fi).",
 "s-fungivel": "Liga o slide anterior (nota de 20 € = identidade qualitativa, fungibilidade) à vida de trabalho.\nCuidado: não se trata de culpar quem tem trabalhos indiferenciados. Diz explicitamente que tratar pessoas como peças é uma escolha da organização (voltamos a isto no DR2.2), e que a lei protege o trabalhador seja qual for a função.\nPara quem não está a trabalhar: pode usar um trabalho anterior, o trabalho em casa, ou o emprego que procura.\nA pergunta final prepara o «Fale-me de si»: o que puseram na coluna da direita é material para a resposta.",
 "s-extremos": "Substitui os antigos slides de Leibniz e de Heraclito (guardados em archive/). Os dois autores servem de extremos: nenhum mudar / tudo muda. A verdade prática está no meio, e é isso que vamos usar.\nNa votação, puxa por quem diz «em parte»: o que é que fica da cabeleireira na técnica de informática? (atendimento, paciência, atenção ao cliente, gestão do tempo). São as «competências transferíveis»: palavra útil para o CV.",
 "s-essencial-trabalho": "Vem a seguir ao slide teórico das propriedades essenciais e acidentais. Clica na resposta mais votada (braço no ar).\nFontes: categoria C para veículos pesados de mercadorias (Código da Estrada / IMT); inscrição obrigatória na Ordem dos Enfermeiros para exercer (Estatuto da Ordem dos Enfermeiros). A fotografia no CV não é exigida por lei.\nA pergunta final é pessoal mas leve. Quem quiser, partilha.",
 "s-meu-navio": "Sessão B começa aqui. Folha em branco, individual. Não é um desenho para avaliar a qualidade: três caixas e uma barra chegam.\nA quilha (a viga do fundo do casco, onde assenta a estrutura) é a metáfora central: o que fica quando as tábuas mudam. Exemplos para desbloquear: «gosto de resolver problemas», «sou de confiança», «dou-me bem com pessoas», «trabalho bem com as mãos».\nQuem não quiser expor a vida pode inventar uma personagem (regra 4 do grupo).",
 "s-fale-de-si": "Aplicação direta do navio. As tábuas dão o passado, o presente e o futuro; a quilha dá a coerência, que é o que o recrutador quer ouvir: alguém que muda mas sabe quem é.\nNota sobre o «Não»: perguntas sobre vida privada, saúde, religião, gravidez, etc. não devem ser feitas numa entrevista; o candidato não tem de responder. Sem entrar em pormenores jurídicos: o Código do Trabalho protege a reserva da vida privada (artigos 16.º e 17.º) e proíbe a discriminação no acesso ao emprego (artigo 24.º).\n10 minutos a escrever. Quem acabar cedo, corta o texto até caber em 1 minuto a falar.",
 "s-entrevista": "Dois minutos por par (1 minuto cada) mais a dica: com a explicação, conta 15–20 minutos. Usa o temporizador de 1 minuto para toda a sala ao mesmo tempo: «candidatos, começar!».\nA grelha pode ser copiada para a folha. Se houver tempo, pede a dois voluntários que façam a simulação à frente da turma.\nEsta resposta é material para a apresentação oral do fim do DR.",
 "s-pesquisa-nokia": "Substitui a pesquisa sobre Plutarco (guardada em archive/). Ligação para a vida profissional: as empresas também mudam de tábuas, e quem lá trabalha tem de se adaptar.\nPergunta extra, se houver tempo: conheces outra empresa ou profissão que tenha mudado tudo? (bancários com o multibanco, tipógrafos com o computador, telefonistas…)",
 "s-para-que-2": "Fecho do bloco. O bilhete de saída é uma frase no fundo da folha; recolhe as folhas se quiseres guardar material para a apresentação oral.",
 "s-palavra": "Vem depois do slide de Ricoeur (idem e ipse). Ninguém mostra a folha: é uma autoavaliação.\nNa partilha, pergunta só: o que escreveram como «coisa concreta»? (pôr alarme, apontar na agenda, dizer «não consigo até sexta, consigo até terça»).",
 "s-palavra-jogo": "Jogo rápido de braço no ar. Casos fictícios; se alguém quiser contar um caso real, lembra a regra: criticamos ideias, nunca pessoas.",
 "s-sem-rosto": "Vem depois dos slides de Levinas (o Mesmo e o Outro; o rosto). Ligação: o rosto pede-me uma resposta; no email o rosto desaparece, mas a pessoa continua lá.\nQuem tiver computador ou telemóvel escreve como se fosse um email (pode enviar para o formador); os outros escrevem na folha.\nNa correção, lê duas ou três respostas em voz alta e confronta com os 5 passos. Erros típicos: pedir desculpa demasiado, prometer «o mais rápido possível» em vez de uma hora concreta, responder também em maiúsculas.",
 "s-atendimento": "Teatro em grupos de três (ver preferência por atividades dinâmicas). Os grupos sobem à frente um de cada vez; se o tempo for curto, fazem todos ao mesmo tempo e só um grupo apresenta.\nLigação com Levinas: frente a frente, o rosto do outro pede uma resposta antes de qualquer regra. Ligação com o mundo do trabalho: no atendimento ao público, isto é metade do emprego.\nDebate final em 5 minutos a partir da grelha do observador.",
 "s-para-que-3": "Fecho do bloco DR1.3.",
 "s-recrutador": "Vem depois do «eu-espelho» (Cooley). Jogo rápido, de braço no ar.\nA ideia não é fingir ser outra pessoa: é saber que imagem estamos a dar sem querer.\nFotografia no CV: não é obrigatória em Portugal; muitos modelos (como o Europass) permitem-na, mas é opcional.",
 "s-pesquisa-me": "Atividade no telemóvel ou computador. É privada: ninguém mostra o ecrã. A alternativa (figura pública) garante que ninguém fica de fora.\nSe ninguém tiver email profissional, podem criar um no fim da aula (5 minutos): nome.apelido@ num serviço gratuito.",
 "s-defeitos": "Vem depois da análise das vinte afirmações: usa a folha que já fizeram.\nO par ajuda a encontrar o exemplo verdadeiro (o colega costuma ver qualidades que o próprio não vê: outra vez o eu-espelho).\nO perfil do CV é o parágrafo curto no topo, com 2 ou 3 frases. Junta-se ao «Fale-me de si» do bloco DR1.2.",
 "s-para-que-4": "Fecho do bloco DR1.4.",
 "s-org": "Bloco novo, do DR2 (Deontologia na construção da cultura organizacional): pertença e lealdade no coletivo; autonomia e responsabilidade. Cabe em duas sessões de 100 minutos.\nSessão A: quem decide? (votação), 10; vertical e horizontal, 15; joga V ou H, 10; régua das organizações (folha), 15; organigrama (folha), 20; como reagir, 15; teatro (preparação), 15.\nSessão B: teatro (apresentações), 25; dilema do chefe, 15; onde trabalho melhor? (folha), 15; anúncios, 10; para que serve, 5; jogo, 10; glossário, 10.\nPonte com o bloco DR1.1: Hegel já distinguia o reconhecimento vertical (senhor e servo) do horizontal (entre iguais).",
 "s-org-ideia": "Votação rápida de braço no ar. Não corrijas: a revelação é que a resposta depende da estrutura. Pergunta a quem tem experiência: «onde trabalhaste, o que acontecia se fosses direto ao diretor?»",
 "s-org-conceito": "Conceitos-chave em diagrama. Hierarquia: cadeia de comando (quem responde a quem). Plana: poucos ou nenhuns níveis intermédios.\nNão apresentes uma como boa e outra como má: as duas têm vantagens (o jogo seguinte mostra-as).",
 "s-org-classificar": "Jogo rápido de braço no ar. As explicações mostram vantagens e desvantagens de cada lado.",
 "s-org-regua": "Não há uma resposta única: o objetivo é justificar. Pistas: Exército e hospital muito verticais (cadeia de comando, segurança); cadeia de comida rápida vertical e com procedimentos para tudo; cooperativa e oficina pequena mais horizontais.\nEsta escola: diretor, subdiretor, conselho pedagógico, coordenadores, professores… mas também equipas pedagógicas que decidem em conjunto. Bom exemplo de «no meio».\nValve: o manual de 2012 é público (media.steampowered.com/apps/valve/Valve_Handbook_LowRes.pdf). Nota que é a descrição que a empresa faz de si própria.",
 "s-org-organigrama": "Folha em branco, individual. Quem nunca trabalhou faz o da escola ou o de um sítio que conhece bem (um clube, uma loja do bairro).\nO passo 3 é o mais útil: muitas vezes quem decide não é quem manda no papel. Pergunta: «as setas foram todas para o chefe?»",
 "s-org-reagir": "É a resposta à pergunta do Daniel: como devem os formandos reagir a cada cultura. Lê em voz alta e pede um exemplo vivido para cada ponto.\nRegulamento interno: muitas empresas têm um; o trabalhador pode pedir para o consultar.",
 "s-org-teatro": "5 minutos para preparar, cerca de 3 minutos por cena. Com turmas grandes, faz dois grupos A e dois grupos B.\nDebate: na vertical, o trabalhador fala com o chefe de secção (não vai direto ao gerente), por escrito e com antecedência. Na horizontal, tem de negociar ele próprio a troca com um colega e levar a solução à reunião.\nSegunda situação, se houver tempo: «viste um colega a fazer uma coisa perigosa».",
 "s-org-dilema": "Dilema do programa do DR2 (ética centrada no dever; pertença e lealdade no coletivo). Vota primeiro, discute depois; não há resposta que garanta zero riscos, e é honesto dizê-lo.\nAlterar a data de validade é uma prática ilegal e perigosa para a saúde pública; quem pode receber denúncias é a ASAE. Se a discussão for para aí, verifica o enquadramento atual antes de dar pormenores.\nCódigo do Trabalho, art. 128.º, n.º 1, e): «Cumprir as ordens e instruções do empregador respeitantes a execução ou disciplina do trabalho, bem como a segurança e saúde no trabalho, que não sejam contrárias aos seus direitos ou garantias».",
 "s-org-perfil": "Questionário caseiro de reflexão, não validado: diz isso claramente à turma. Liga ao slide seguinte: os anúncios de emprego dão pistas sobre a cultura da empresa.",
 "s-org-anuncios": "Frases inventadas, mas típicas de anúncios reais. Trabalho de casa opcional: trazer um anúncio verdadeiro e classificá-lo na régua.",
 "s-para-que-5": "Fecho do bloco DR2.2.",
 "s-glossario5": "Inclui também conceitos novos dos blocos DR1.2 e DR1.3 (fungível, competências transferíveis, ipse), para o glossário pessoal da apresentação oral.",
 "s-jogo5": "Jogo para a turma: projetar, ler a pergunta em voz alta e pedir respostas de braço no ar (ou com os dedos, 1 a 3) antes de clicar. Teclas 1 a 3 escolhem; Enter passa à seguinte.",
 "s-tel-nome": "Alternativa ao jogo projetado: cada formando joga no seu telemóvel (aluno.html?a=nome) e envia o nome, as respostas do jogo e 2 respostas escritas. Recebes um email por formando e fica tudo na folha de cálculo «CP 4 · respostas dos formandos» no teu Google Drive. Só funciona com o site publicado (GitHub Pages) e com o endereço do Apps Script em config.js. Ver LEIA-ME-telemovel.md.",
 "s-tel-navio": "Alternativa ao jogo projetado: cada formando joga no seu telemóvel (aluno.html?a=navio) e envia o nome, as respostas do jogo e 3 respostas escritas. Recebes um email por formando e fica tudo na folha de cálculo «CP 4 · respostas dos formandos» no teu Google Drive. Só funciona com o site publicado (GitHub Pages) e com o endereço do Apps Script em config.js. Ver LEIA-ME-telemovel.md.",
 "s-tel-gage": "Alternativa ao jogo projetado: cada formando joga no seu telemóvel (aluno.html?a=gage) e envia o nome, as respostas do jogo e 3 respostas escritas. Recebes um email por formando e fica tudo na folha de cálculo «CP 4 · respostas dos formandos» no teu Google Drive. Só funciona com o site publicado (GitHub Pages) e com o endereço do Apps Script em config.js. Ver LEIA-ME-telemovel.md.",
 "s-tel-identidade": "Alternativa ao jogo projetado: cada formando joga no seu telemóvel (aluno.html?a=identidade) e envia o nome, as respostas do jogo e 2 respostas escritas. Recebes um email por formando e fica tudo na folha de cálculo «CP 4 · respostas dos formandos» no teu Google Drive. Só funciona com o site publicado (GitHub Pages) e com o endereço do Apps Script em config.js. Ver LEIA-ME-telemovel.md.",
 "s-tel-organizacoes": "Alternativa ao jogo projetado: cada formando joga no seu telemóvel (aluno.html?a=organizacoes) e envia o nome, as respostas do jogo e 3 respostas escritas. Recebes um email por formando e fica tudo na folha de cálculo «CP 4 · respostas dos formandos» no teu Google Drive. Só funciona com o site publicado (GitHub Pages) e com o endereço do Apps Script em config.js. Ver LEIA-ME-telemovel.md.",
  "s-d1": "Segunda parte do DR1. Até aqui a pergunta foi «quem sou eu?» e «quem é o outro?». Agora é «como devo tratá-lo?», sempre com casos do trabalho. Nas cenas, «eu» sou a figura laranja e «o outro» é a figura azul.",
  "s-d1-caso": "Caso de abertura, inventado para a aula. Contar os braços com os botões + e −. Não comentar as escolhas: pedir só a razão de cada uma e escrever no quadro as palavras que surgirem (medo, pena, justiça, «não é comigo»).\nClique 2: anuncia o percurso. O caso volta no último slide do bloco.\nCuidado: pode haver formandos imigrantes na sala. O caso serve para pensar a situação, não para pôr ninguém em evidência.",
  "s-d1-empatia": "O que mostra: «o outro» (azul) sobrecarregado; «eu» (laranja) a olhar.\nClique 1: empatia. No balão aparece a cara do outro: ponho-me no lugar dele.\nClique 2: reação compassiva. Já não é só perceber: é querer que aquilo acabe.\nClique 3: solidariedade. A figura laranja atravessa a sala e fica ao lado do outro. As duas caras mudam.\nClique 4: só a solidariedade se vê. A empatia e a compaixão sem ação não mudam nada para o outro. Ligar às respostas do caso do Amadou: quem ficou calado pode ter sentido empatia e compaixão.\nLigação ao bloco DR1.3: o rosto do outro, em Levinas, chama-me à responsabilidade.\nAs três definições foram escritas para a aula, em linguagem simples.",
  "s-d1-empatia-jogo": "Seis frases ouvidas no trabalho. Ajudam a distinguir sentir (empatia), querer (compaixão) e agir (solidariedade). Em cada compaixão, perguntar: «E o que seria a solidariedade aqui?»",
  "s-d1-kant": "O que mostra: duas mini-cenas. À esquerda, chegar a um prémio (a moeda); à direita, uma fila de colegas.\nInício: «eu» subo para cima do colega para chegar à moeda. Uso-o só como meio, como se fosse um escadote.\nClique 1: a alternativa: os dois levantam juntos. Trato o outro também como um fim, isto é, como alguém com objetivos próprios. Para Kant, o que torna uma ação boa é a regra que sigo (o dever), não o resultado.\nClique 2: o primeiro teste de Kant: posso querer que a minha regra valha para todos? Exemplo: «minto quando me dá jeito». Os balões aparecem um a um.\nClique 3: se todos mentissem, deixava de haver confiança e mentir deixava de funcionar. A regra destrói-se a si própria: por isso não é aceitável.\nClique 4: a distinção de Kant entre preço e dignidade. Ligação ao bloco DR1.2 («És fungível no trabalho?»): um trabalhador pode ser substituído numa função, mas uma pessoa não tem preço.\nVoltar ao Amadou: rir dele para não ficar de fora é usá-lo como meio. E se todos fizessem o mesmo a quem chega?\nRigor: os dois testes são versões simplificadas de duas formulações do imperativo categórico (a da lei universal e a da humanidade como fim).",
  "s-d1-mill": "O que mostra: três decisões possíveis num local de trabalho, cada uma com cinco pessoas. Laranja a sorrir: fica melhor. Cinzento: fica pior.\nClique 1: para os utilitaristas, o que torna uma ação boa são as suas consequências. Entre A e B, a certa é a B. Bentham chamou-lhe o princípio da maior felicidade; Mill desenvolveu-o. Exemplo para a turma: mudar a escala de turnos de forma a que quatro fiquem melhor e um pior.\nClique 2: a objeção clássica. Na decisão C os quatro ficam contentes porque um colega (azul) foi posto de parte. Se só contarmos o total, parece a melhor.\nClique 3: a resposta de Mill (capítulo 5 de Utilitarismo): as regras de justiça e os direitos individuais são o que mais protege o bem-estar de todos a longo prazo; uma sociedade onde qualquer um pode ser sacrificado não é feliz. Mill acrescentou também que os prazeres diferem em qualidade, não só em quantidade.\nVoltar ao Amadou: quatro colegas a rir e um humilhado é a decisão C.\nComparar com Kant: Kant olha para a regra; Mill olha para o resultado. No caso do Amadou chegam à mesma conclusão por caminhos diferentes.",
  "s-d1-kant-mill": "Seis frases de decisões no trabalho. No fim, perguntar: «Com qual dos dois decides mais vezes?» e «Há casos em que os dois discordam?» (o da loja que fecha costuma dividir a sala). Ligação ao bloco DR1.3: manter a palavra (Ricoeur) é um dever no sentido de Kant.",
  "s-d1-equidade": "O que mostra: a entrada de uma empresa. «Eu» à direita; «o outro», em cadeira de rodas, à esquerda.\nClique 1: igualdade: a escada é a mesma para todos. Eu subo. O outro tem exatamente o mesmo direito de entrar, mas não consegue. A cara dele muda. Definem-se igualdade e diferença.\nClique 2: equidade: aparece a rampa. Não é um privilégio: é o que falta para o direito de entrar ser real. Agora entram os dois.\nClique 3: exemplos do trabalho que costumam surgir: horário flexível para quem tem filhos pequenos, posto de trabalho adaptado, mais tempo de formação para quem começa de mais longe, materiais noutra língua.\nIdeia a reter: a igualdade é o objetivo (os mesmos direitos); a equidade é muitas vezes o caminho (tratar de forma diferente o que é diferente).\nAs definições foram escritas para a aula.",
  "s-d1-direitos": "Dois conceitos-chave do programa, numa distinção simples: nos direitos civis, o Estado tem de se abster (não me prender, não me calar); nos direitos sociais, o Estado tem de agir (dar escola, saúde, proteção).\nLigação à equidade: os direitos sociais são a «rampa» do slide anterior, à escala de um país.\nSeis casos para classificar, de braço no ar. Na Constituição portuguesa, os primeiros estão nos «direitos, liberdades e garantias» e os segundos nos «direitos económicos, sociais e culturais».",
  "s-d1-diversidade": "O que mostra: cinco pessoas diferentes (as cores). «Eu» sou a laranja.\nClique 1: tolerância. Cada um no seu canto: não te faço mal, mas também não me aproximo. É o mínimo.\nClique 2: aceitação. Aproximam-se: reconheço que tens direito a ser como és.\nClique 3: unidade na diversidade. Formam uma equipa. A diferença deixa de ser um problema a gerir e passa a ser uma vantagem (mais línguas, mais experiências, mais ideias). É também o lema da União Europeia («Unida na diversidade»), que volta no DR4.\nClique 4: prospetividade (o programa escreve «prospectividade»): a diversidade, a aceitação e a tolerância são elementos prospetivos, isto é, condições para o futuro de sociedades cada vez mais diversas.\nClique 5: pergunta para a turma, com exemplos concretos do local de trabalho.\nAs definições foram escritas para a aula.",
  "s-d1-muro": "O que mostra: «eu» e «o outro», cada um do seu lado. A cada clique ergue-se um tijolo. Em cada um, pedir um exemplo à turma antes de dar a definição.\n1 · Racismo e xenofobia: tratar pior alguém pela cor da pele ou origem étnica (racismo) ou por ser estrangeiro (xenofobia).\n2 · Desigualdade de género: tratar de forma diferente mulheres e homens (salário, promoções, tarefas).\n3 · Estado civil: discriminar por ser solteiro, casado, divorciado, ter ou não ter filhos.\n4 · Homofobia e transfobia: hostilidade para com pessoas pela sua orientação sexual ou identidade de género.\n5 · Deficiência (o programa diz «portadores de necessidades especiais»): excluir em vez de adaptar.\n6 · Religião ou crenças religiosas: discriminar por ter uma religião, ou por não ter.\n7 · Idadismo (o programa escreve «edaísmo»): discriminar pela idade, novos ou velhos.\nClique 8: o muro desfaz-se e as figuras aproximam-se. O n.º 2 do artigo 13.º da Constituição diz que ninguém pode ser privilegiado, beneficiado, prejudicado, privado de qualquer direito ou isento de qualquer dever em razão de ascendência, sexo, raça, língua, território de origem, religião, convicções políticas ou ideológicas, instrução, situação económica, condição social ou orientação sexual. No trabalho, o Código do Trabalho (artigos 24.º e 25.º) acrescenta, entre outros, a idade, o estado civil, a deficiência e a identidade de género.\nClique 9: partilha. Lembrar as regras do grupo: contam-se situações, não se apontam pessoas.\nLigação à equidade (a rampa). A dignidade de cada pessoa volta no DR2, com Kant.",
  "s-d1-discrimina": "Oito situações, inventadas para a aula. Duas não são discriminação: um requisito real do trabalho (a carta de pesados) e um ajuste por respeito (a reunião). Servem para mostrar que tratar de forma diferente nem sempre é discriminar. Em cada «sim», pedir o nome do tijolo.",
  "s-d1-para-que": "Fecho do bloco, como nos anteriores. Quatro utilidades práticas, uma por clique.\nClique 5: voltar ao caso de abertura e repetir a votação de braço no ar. Comparar com a primeira. Bilhete de saída (no telemóvel ou na folha): a resposta e a razão, usando pelo menos uma das ferramentas (sentir/querer/agir, equidade, tolerância e aceitação).",
  "s-dr2": "Início do DR2 (contexto profissional). O programa abre com a ética enquanto pensamento da ação e com a deontologia, ética centrada no dever: por isso Kant e Mill abrem este DR, e o bloco DR2.2 («Quem manda aqui?») vem a seguir.\nO caso do Amadou (DR1) pode ser retomado aqui: os formandos já o conhecem.",
  "s-d2-deontologia": "Ponte entre o DR1 e o DR2. A palavra «deontologia» tem dois sentidos, e o programa usa os dois: a ética centrada no dever (Kant) e os códigos de conduta no contexto profissional (que vêm mais à frente no DR2).\nClique 1: o sentido filosófico. Clique 2: o sentido profissional; perguntar se alguém conhece o código deontológico de uma profissão. Clique 3: anuncia os dois slides seguintes.\nA etimologia (do grego deon, o que é devido, o dever, e logos, estudo) e a definição foram escritas para a aula.",
  "s-d1-apresentacao": "Apresentação oral no fim do DR, como combinado para todos os DR: tema à escolha do formando e uma atividade de sala de aula que queira destacar. Três minutos por pessoa; os outros fazem uma pergunta. Pode preparar-se numa aula e apresentar-se na seguinte.",
  "s-jogo-d1": "Jogo de revisão do bloco, projetado. A mesma versão está no slide seguinte, para o telemóvel.",
  "s-tel-conduta": "Os formandos jogam no telemóvel e respondem a três perguntas escritas; as respostas chegam como nos outros blocos.",
  "s-corpo": "O que mostra: uma figura feita de pontos. Cada ponto é uma «tábua». Azul-escuro: tábua original, de hoje. Laranja: tábua já trocada. Claro: acabou de ser trocada. Há dois níveis, escolhidos nos botões «Nível»; o tempo é o mesmo nos dois.\nAntes de carregar: pedir palpites. «Daqui a dez anos, quanto do vosso corpo de hoje ainda cá está?»\nNÍVEL 1, o corpo (tecidos e células). Carregar em «Deixar passar o tempo». Os primeiros meses passam devagar: a pele (o contorno) fica toda laranja em menos de um mês e continua a piscar, porque não para de se renovar; os glóbulos vermelhos (os pontos pequenos) estão todos trocados ao fim de quatro meses. Depois o tempo acelera: o esqueleto (a coluna e as costelas) muda aos poucos, cerca de 10 % por ano; ao fim de dez anos resta menos de metade. Os neurónios do córtex (os pontos da cabeça) não mudam.\nPergunta de passagem: «Então o cérebro é a parte de nós que nunca muda?»\nNÍVEL 2, dentro de um desses neurónios (moléculas e átomos). Carregar em «Repor», mudar de nível e deixar passar o tempo outra vez. A célula é a mesma, mas a matéria de que é feita não: a água (os pontos pequenos) vai sendo trocada, metade em cerca de uma semana; as proteínas (os pontos da membrana e do interior) duram dias ou semanas, porque o metabolismo da célula as desfaz e volta a fazer. Há exceções: algumas proteínas dos poros do núcleo duram anos. O ADN (os pontos dentro do núcleo) é a molécula mais estável da célula, mas também não fica igual: sofre danos todos os dias e a célula repara-os, trocando nucleótidos; por isso os seus átomos também vão mudando, só que devagar. A maior parte do carbono do ADN mantém-se, e é isso que permite datar a idade dos neurónios com carbono-14. Nada na célula fica com exatamente os mesmos átomos.\nA barra deslizante permite voltar atrás e parar num momento qualquer; pode mudar-se de nível com o tempo parado, para comparar o mesmo momento nos dois.\nPergunta final: se mudam as células e, dentro das que ficam, os átomos, o que fica? A organização, a forma: as mesmas ligações, feitas de matéria nova. É exatamente o navio de Teseu, e é a ponte para a memória (Locke), para o cientista louco e, mais tarde, para Phineas Gage.\nRigor: é um mito que «todas as células do corpo se renovam a cada sete anos». A animação é um modelo: cada ponto representa muitas células ou moléculas. Os valores do nível 1 são os do slide original. No nível 2: a meia-vida da água no corpo de adultos sedentários ronda os 7,5 dias (Shimamoto e Komiya, 2003); as proteínas do cérebro duram em média 9 dias em ratinhos (Price e colegas, 2010), e em humanos o valor não é bem conhecido, pelo que o modelo usa um mês; as proteínas de vida muito longa dos poros do núcleo foram encontradas em ratos (Savas e colegas, 2012). Para o ADN não há um valor medido da fração de átomos trocados por ano: por isso a linha do ADN não mostra percentagem, só «o mais lento de todos», e os pontos mudam devagar apenas para o mostrar.\nA caixa «Quantos anos até sermos feitos só de átomos novos?»: não há um número certo. O valor mais citado (cerca de 98 % dos átomos renovados num ano) é de Paul Aebersold, do laboratório de Oak Ridge, em 1953, com base em experiências com radioisótopos; é uma estimativa antiga, apresentada num relatório sem dados publicados, e há quem a considere exagerada (o osso, por exemplo, muda muito mais devagar). O que é seguro: a água, que é a maior parte dos nossos átomos, troca-se em semanas; e há matéria que nunca é trocada, como o esmalte dos dentes e as proteínas do centro do cristalino do olho, datadas com carbono-14. Por isso a resposta honesta é «quase tudo em poucos anos, tudo nunca».",
  "s-gage-ponte": "Slide de ligação ao programa. Clique 1: o que vimos na aula anterior. Clique 2: DR1. Clique 3: DR2. Clique 4: pergunta.\n\nAs duas frases entre aspas são do texto do programa (DR1 e DR2, ver o slide «Programa»).\n\nIdeia para a turma: o caso Gage serve para os dois domínios. Para o DR1, pergunta se a identidade muda quando muda o carácter (o mesmo e o outro). Para o DR2, pergunta o que acontece ao juízo moral (o dilema do elétrico, Kant e Mill) quando o córtex pré-frontal é ferido. Isto prepara o slide «E se o córtex pré-frontal estiver ferido?».\n\nSapolsky (Behave, capítulo sobre a adolescência): o córtex frontal é a última região a amadurecer (por volta dos 25 anos) e, por isso, a menos determinada pelos genes e a mais moldada pela experiência e pela cultura. Confirma esta formulação no livro antes de a usar como citação.",
  "s-eletrico-jogo": "Jogo em toda a turma: projeta neal.fun/absurd-trolley-problems. O jogo está em inglês: lê cada dilema em voz alta e traduz. Antes de clicar, a turma vota de braço no ar; depois, pergunta «Kant ou Mill?». Liga aos slides do DR2.1 (Kant: há coisas que não se fazem; Mill: conta as consequências).\n\nO botão «E agora?» faz a ponte para Gage: que parte do cérebro trabalhou nas decisões? Não respondas ainda; a resposta vem no slide «E se o córtex pré-frontal estiver ferido?».",
  "s-gage-3d": "Reconstrução 3D com anatomia real. Clique 1: a explosão (a barra atravessa a cabeça e fica «congelada» a meio do voo, como nas reconstruções publicadas). Clique 2: o trajeto (crânio transparente). Clique 3: o córtex destruído (vermelho-escuro). Clique 4: as fibras cortadas (vermelho) e uma amostra das outras (azul).\n\nDe onde vem o modelo: cérebro FreeSurfer fsaverage (média de 40 ressonâncias); crânio BodyParts3D, ajustado à volta desse cérebro; fibras do atlas de tractografia HCP1065 (média de 1065 pessoas). A barra tem as medidas de Harlow: 109 cm, 3,2 cm de diâmetro, ponta afilada.\n\nO trajeto foi ajustado à reconstrução de Van Horn e colegas (PLoS ONE, 2012): entrada por baixo do arco zigomático esquerdo, atrás do olho esquerdo, saída perto da sutura sagital, à frente da coronal, sem atravessar a linha do meio. No nosso modelo a barra atravessa 3,9% do córtex (Van Horn: 3,97%) e as percentagens por região batem certo: sulco orbital 95% (91%), sulco frontal médio 79% (80%), giro orbital 40% (39,5%), cíngulo anterior 24% (23%). Nenhum dano direto à direita.\n\nRigor: o crânio e o cérebro não são os de Gage (o cérebro de Gage não foi preservado; só o crânio, em Harvard). É uma reconstrução sobre um cérebro médio, como a de Van Horn. Os 11% de substância branca são o valor de Van Horn; no ecrã, a proporção de fibras vermelhas é a de uma amostra de feixes do atlas, não uma medida.",
  "s-cerebro-3d": "Modelo interativo com anatomia real: arrasta para rodar, roda do rato (ou dois dedos) para aproximar, clica numa parte ou num botão. «Crânio» alterna entre transparente, opaco e escondido. «Ver por dentro» mostra o tálamo, os núcleos da base (caudado, putâmen), o hipocampo, a amígdala, o corpo caloso e os ventrículos; clicar num deles (ou no botão Tálamo) destaca-o. «Fibras tálamo ↔ pré-frontal» mostra a radiação talâmica anterior, um feixe real do atlas HCP1065: é o que a lobotomia cortava.\n\nLobos segundo o atlas de Desikan-Killiany do FreeSurfer; córtex pré-frontal = áreas de Brodmann 8–11, 44–47, 25 e 32 (atlas PALS-B12). O giro do cíngulo e a ínsula aparecem com cores próprias: não pertencem a nenhum dos quatro lobos clássicos.\n\nSugestão: começa com o crânio opaco, passa a transparente, depois escondido; liga «Fibras» antes da lobotomia.",
  "s-ligacoes": "Clique 1: neurónios (o sinal percorre o axónio). Clique 2: glia. Clique 3: substância cinzenta e branca. Clique 4: pergunta.\n\nNúmeros: cerca de 86 mil milhões de neurónios e outras tantas células não neuronais (Azevedo e colegas, 2009, contagem por fracionador isotrópico). A ideia de «dez vezes mais glia» é um mito (von Bartheld e colegas, 2016).\n\nLigação: o slide seguinte fala de 11% de substância branca destruída em Gage; a leucotomia corta precisamente substância branca. A pergunta prepara isto: as regiões continuam lá, mas deixam de falar umas com as outras.",
  "s-gage-eletrico": "Clique 1: o estudo. Clique 2: o resultado. Clique 3: Kant e Mill. Clique 4: pergunta.\n\nKoenigs e colegas (Nature, 2007): seis doentes com lesões bilaterais do córtex pré-frontal ventromedial deram respostas anormalmente «utilitaristas» nos dilemas pessoais de alto conflito (como empurrar alguém da ponte); nos dilemas impessoais e não morais responderam como os controlos. Os autores concluem que as emoções têm um papel necessário nestes juízos.\n\nLigação a Gage: Damásio e colegas (1994) situaram a lesão de Gage nesta mesma zona, nos dois hemisférios; estudos mais recentes (2004, 2012) apontam sobretudo para o lado esquerdo. Não digas que Gage respondia assim: ninguém lhe fez estes testes.\n\nA pergunta final retoma Sapolsky: o cérebro é necessário, mas as regras aprendem-se com os outros.",
  "s-lobotomia-3d": "Reconstrução 3D só da lobotomia transorbital (Freeman, 1946). Clique 1: a entrada, por cima do olho, sob a pálpebra superior, a 3 cm do meio, paralelo ao nariz. Clique 2: o martelo fura o teto da órbita; a ponta vai até 5 cm (marcas de 1 cm no instrumento). Clique 3: primeiro corte (o cabo puxado para fora, a ponta varre para dentro). Clique 4: corte frontal profundo (1948): volta a meio, empurra até 7 cm e varre para dentro e para fora. Clique 5: o outro lado. Clique 6: o resultado.\n\nAs fibras amarelas são a radiação talâmica anterior real (atlas HCP1065); quando o plano de corte (vermelho) as atravessa, a parte do lado frontal fica cinzento-escura: desligada do tálamo. No modelo, o primeiro corte apanha cerca de 22% destas fibras e o corte profundo outros 50%.\n\nRigor: a técnica segue a descrição do próprio Freeman citada por Valenstein (orbitoclasto sob a pálpebra a 3 cm do meio, paralelo ao nariz, 5 cm, cabo puxado para fora, volta a meio, mais 2 cm). Os ângulos de varrimento (28° e ±20°) são aproximados: Freeman variava-os. Os doentes eram postos inconscientes com eletrochoque; não havia anestesia nem esterilização garantida.\n\nLigação à identidade: os doentes ficavam calmos, mas apáticos, sem iniciativa, «infantis» (Freeman: «infância induzida cirurgicamente»). Pergunta para a turma: depois disto, é a mesma pessoa? Quem decidiu por ela?",
 "s-projeto": "O trabalho de grupo substitui a apresentação oral no fim de cada DR. Um PowerPoint por grupo (3 ou 4 pessoas) sobre um caso ou um tema à escolha, que tem de mobilizar os quatro DR: em cada DR, pelo menos um slide com uma ideia (um conceito do DR explicado por palavras próprias), um com um caso real (do trabalho ou da vida de alguém do grupo) e um com o que se faz (uma regra de conduta, uma queixa, um direito que se usa). Cada clique mostra uma linha da grelha.\nO exemplo do Amadou (caso do bloco DR1.5) mostra como um caso atravessa os quatro contextos: privado, profissional, institucional e macroestrutural.\nCalendário: durante as aulas, guardar material; nas últimas aulas, quatro oficinas (uma por DR) e, na última, apresentações de 15 minutos. No telemóvel (atividade «grupo»): nomes do grupo e primeira ideia.",
 "s-mapa": "Quadro gerado automaticamente a partir das etiquetas de cada slide (atributo data-dr no index.html). Mostra que os quatro DR atravessam a unidade: por exemplo, os blocos do DR1 sobre identidade usam muitos casos do mundo do trabalho (DR2). Para mudar uma etiqueta, edita data-dr=\"1,3\" no slide.",
 "s-cod-caso": "Abertura do bloco (10 minutos). Votação de braço no ar; contar com + e −. Não dar resposta: pedir a dois formandos, com votos diferentes, que expliquem a escolha. A pergunta «leal a quem?» fica no ar e volta no slide «Pertença e lealdade».\nConteúdo do programa (DR2): códigos de conduta no contexto profissional; pertença e lealdade no coletivo. Critério de evidência do DR1: relatar princípios de conduta e emitir opinião fundamentada.",
 "s-cod-codigo": "10 minutos. Critério de evidência do DR1: interpretar códigos deontológicos. Os andares aparecem de baixo para cima: a lei (para todos), o código deontológico (para uma profissão, normalmente aprovado pela ordem ou associação profissional), o código de conduta (para uma organização) e os costumes da equipa (não escritos).\nIdeia a reter: cada andar assenta no de baixo. Um código de conduta não pode mandar fazer o que a lei proíbe (ligar ao dilema das etiquetas da carne, no bloco DR2.2).\nPerguntar quem já assinou um código de conduta ao entrar numa empresa. Muitas empresas publicam o seu na Internet: pode ser trabalho para casa encontrar o de uma empresa conhecida.",
 "s-cod-ler": "10 minutos. Interpretar um código: ler uma regra geral e decidir se um caso concreto a cumpre ou a viola. O código é inventado, mas as cinco regras (respeito, sigilo, presentes e conflito de interesses, uso dos bens, comunicação de irregularidades) aparecem na maioria dos códigos de conduta reais.\nA turma pode responder no telemóvel (botão «Responder no telemóvel», acrescentado automaticamente aos questionários). Discutir o caso do chefe: um código vale para todos, de cima a baixo.",
 "s-cod-lealdade": "15 minutos. Competência do DR2: exprimir sentido de pertença e de lealdade para com o coletivo profissional. Critério: identificar pertença e lealdade em contextos vários.\nOs círculos aparecem de dentro para fora: sou leal aos meus valores, à equipa, à organização, ao cliente e à sociedade. O conflito do caso inicial nasce quando dois círculos puxam para lados diferentes (o amigo e a empresa). Pedir exemplos de pertença fora do trabalho: clube, família, bairro, associação, igreja.\nA lei: o dever de lealdade do Código do Trabalho (artigo 128.º, n.º 1, alínea f) fala de não concorrência e de sigilo. Não obriga a encobrir ilegalidades: a Lei n.º 93/2021 protege quem denuncia infrações de boa-fé e obriga as organizações com 50 ou mais trabalhadores a ter um canal de denúncia interno.\nFechar voltando ao caso: na resposta B fui leal ao amigo e à empresa ao mesmo tempo (dei-lhe a oportunidade de parar).",
 "s-cod-multi": "15 minutos. Critérios de evidência do DR2: explicitar situações profissionais de relacionamento com desafios multiculturais; expressar-se e agir face a pessoas, grupos ou organizações de âmbito multicultural segundo uma lógica inclusiva.\nAntes de virar cada cartão, perguntar: o que faziam? Só depois mostrar uma resposta possível (não é a única). A regra geral: muda-se a forma de organizar o trabalho, não o nível de exigência.\nCuidado: há formandos de várias origens na sala. Não pedir a ninguém que fale «em nome» da sua cultura; quem quiser, partilha.\nLigar ao bloco DR1.5 (igualdade e equidade; o muro da intolerância): a lógica inclusiva é a equidade aplicada à equipa.",
 "s-cod-escreve": "20 minutos, em grupos de três ou quatro. Produto: um código de conduta de cinco regras, enviado pelo telemóvel (atividade «codigo») ou escrito numa folha. Pode entrar no trabalho de grupo (parte do DR2).\nBoas regras são concretas e verificáveis («avisamos com 24 horas quando trocamos um turno») e não vagas («somos profissionais»). A regra sobre o que fazer quando alguém falha evita que o código seja só uma lista de proibições.",
 "s-para-que-6": "Fecho do bloco (5 minutos). Bilhete de saída oral ou numa folha.",
 "s-mot-caso": "Abertura (10 minutos). Votação de braço no ar. A segunda pergunta (o que me faria sair) costuma dar respostas diferentes da primeira (o que me faz ficar): é a porta de entrada para a distinção de Herzberg entre o que evita a insatisfação e o que motiva.\nConteúdo do programa: mecanismos de motivação e realização pessoal e profissional e a sua relação com a produtividade.",
 "s-mot-maslow": "15 minutos. A pirâmide sobe um degrau por clique, com um exemplo do trabalho em cada um. Maslow (1943) propôs que só procuramos os degraus de cima quando os de baixo estão razoavelmente satisfeitos.\nRigor: a pirâmide é uma simplificação posterior (Maslow não desenhou uma pirâmide) e a investigação não confirma uma ordem fixa: há quem aceite menos segurança para ter mais realização, e o contrário. Usar como mapa para conversar, não como lei.\nMotivação intrínseca (de dentro: gosto, sentido) e extrínseca (de fora: salário, prémio). Perguntar exemplos de cada uma.",
 "s-mot-herzberg": "10 minutos. A bola começa do lado esquerdo (insatisfeito). No primeiro clique vai para o meio: os fatores de higiene (salário, condições, segurança, chefia) tiram a insatisfação, mas não motivam. No segundo clique vai para a direita: só os fatores motivadores (reconhecimento, responsabilidade, progresso, o trabalho em si) criam vontade.\nLigar ao caso inicial: as razões para sair costumam ser fatores de higiene; as razões para ficar com gosto, fatores motivadores.\nRigor: a teoria de Herzberg (1959) é contestada nos pormenores (para muita gente o salário também motiva), mas a ideia central resiste: resolver os problemas não é o mesmo que criar entusiasmo.",
 "s-mot-jogo": "5 minutos. Seis frases para classificar; pode ser respondido no telemóvel. Em caso de dúvida, a pergunta é: se isto faltasse, eu queixava-me (higiene)? Ou: isto dá-me vontade de fazer mais (motivador)?",
 "s-mot-convergir": "15 minutos. Conteúdos do programa: relação entre motivação e produtividade; convergência entre os objetivos organizacionais e as motivações pessoais; participação na construção dos objetivos organizacionais à luz de uma cultura de rigor.\nOs dois círculos começam afastados. No segundo clique aproximam-se e aparece a zona comum. Pedir exemplos reais de convergência (formação paga pela empresa, prémios de equipa, teletrabalho com objetivos) e de divergência (horas extra não pagas, objetivos impossíveis).\nProdutividade: o que se produz a dividir pelo tempo ou pelos recursos. Trabalhar mais horas não é ser mais produtivo. A cadeia final é uma possibilidade, não uma garantia: os ganhos de produtividade só voltam ao trabalhador se forem partilhados (ligar à concertação social, no DR3).\nCultura de rigor: objetivos claros, medidos e conhecidos por todos; quem participa na definição de um objetivo compromete-se mais com ele.",
 "s-mot-metas": "10 minutos. Conteúdo do programa: o papel da autonomia e da responsabilidade no planeamento e estruturação de metas.\nCada letra aparece com a pergunta que lhe corresponde. O exemplo transforma um desejo vago numa meta: específica (curso de folha de cálculo), mensurável (25 horas, um mapa de turnos feito), alcançável, relevante (serve o trabalho) e com data.\nAutonomia e responsabilidade andam juntas: quem escolhe a meta responde por ela. Ligar às organizações horizontais do bloco DR2.2 (mais autonomia, mais responsabilidade).\nO acrónimo SMART vem do inglês (specific, measurable, achievable, relevant, time-bound); é atribuído a George Doran (1981).",
 "s-mot-escreve": "15 minutos. Individual, com verificação em pares. Envio pelo telemóvel (atividade «meta») ou numa folha. As metas podem ser revistas no fim da unidade: quem cumpriu o primeiro passo?",
 "s-para-que-7": "Fecho do bloco (5 minutos).",
 "s-jogo6": "Jogo de revisão dos blocos DR2.3 e DR2.4: 8 perguntas, 20 segundos cada. A turma responde de braço no ar ou no telemóvel (slide seguinte).",
 "s-tel-motivacao": "O mesmo jogo no telemóvel de cada formando, seguido de três perguntas escritas. As respostas ficam na folha «Avaliação contínua» (atividade «motivacao»).",
 "s-dr3": "Abertura do DR3 (contexto institucional). Do «como trato o outro» (DR1) e do «como se vive numa organização» (DR2) passamos a «o que fazem as instituições»: como se negoceia, a quem se recorre, que políticas existem.",
 "s-con-caso": "Abertura (10 minutos). Votar antes de mostrar a resposta. O salário mínimo (retribuição mínima mensal garantida) é fixado pelo Governo, por decreto-lei, depois de ouvir os parceiros sociais na Comissão Permanente de Concertação Social.\nValores: 870 euros em 2025, 920 euros desde 1 de janeiro de 2026, 970 euros previstos para 2027 no acordo tripartido de outubro de 2024, assinado pelo Governo, pelas quatro confederações patronais e pela União Geral de Trabalhadores (a Confederação Geral dos Trabalhadores Portugueses não assinou). Em setembro de 2026 os sindicatos pediam mais (1 000 e 1 050 euros). Confirmar o valor de 2027 quando for publicado.\nFontes: Lusa/RTP, dezembro de 2025; Diário de Notícias, setembro de 2026.",
 "s-con-mesa": "15 minutos. Cada clique senta um lado da mesa: o Governo; as quatro confederações patronais (Confederação Empresarial de Portugal, da indústria; Confederação do Comércio e Serviços de Portugal; Confederação dos Agricultores de Portugal; Confederação do Turismo de Portugal); e as duas centrais sindicais (Confederação Geral dos Trabalhadores Portugueses – Intersindical Nacional e União Geral de Trabalhadores).\nConcertação social: negociar antes de decidir. Um acordo não precisa de todos: o de 2024 foi assinado sem uma das centrais sindicais. E não é lei: o Governo e a Assembleia da República é que legislam, mas um acordo dá força política à lei.\nLigar ao DR2: a negociação coletiva dentro de uma empresa ou de um setor (contrato coletivo de trabalho) é o mesmo mecanismo, a outra escala. Perguntar: alguém é sindicalizado? Alguém já esteve numa comissão de trabalhadores?\nFonte: Constituição da República Portuguesa, artigo 92.º (Conselho Económico e Social); Lei n.º 108/91.",
 "s-con-politicas": "10 minutos. Critério de evidência do DR3: identificar a diversidade de políticas públicas na sociedade. Cinco tipos de ferramenta, um por clique: proibir (lei), reservar (quotas), apoiar (dinheiro e serviços), educar (campanhas, escola), ouvir (participação).\nExemplos: Código do Trabalho, artigos 24.º (direito à igualdade no acesso a emprego e no trabalho) e 25.º (proibição de discriminação); Lei n.º 4/2019 (quotas de emprego para pessoas com deficiência com grau de incapacidade igual ou superior a 60%: 1% nas médias empresas e 2% nas grandes).\nA mesma situação pede ferramentas diferentes: avaliar é perguntar qual resulta melhor e quanto custa. Pedir à turma que avalie uma política que conheça (passe social, creches gratuitas, apoio à renda).",
 "s-con-organismos": "15 minutos. Conteúdo do programa: organismos institucionais de combate à discriminação, à escala nacional e internacional. Entra-se pela situação («o que me aconteceu») e chega-se ao organismo.\nEm Portugal: Comissão para a Igualdade no Trabalho e no Emprego (pareceres obrigatórios, por exemplo, antes de despedir uma grávida); Comissão para a Igualdade e contra a Discriminação Racial (desde a Lei n.º 3/2024 é uma entidade independente que funciona junto da Assembleia da República; em 2026 ainda aguardava a lei de regulamentação para poder aplicar coimas, e tinha queixas por analisar: bom exemplo para avaliar uma política pública, sem tomar partido); Comissão para a Cidadania e a Igualdade de Género; Instituto Nacional para a Reabilitação; Autoridade para as Condições do Trabalho; Provedor de Justiça (queixas gratuitas contra a administração pública).\nFora de Portugal: Conselho da Europa (46 Estados; não confundir com a União Europeia), com o Tribunal Europeu dos Direitos Humanos e a Comissão Europeia contra o Racismo e a Intolerância (sexto relatório sobre Portugal, junho de 2025); União Europeia (diretivas sobre igualdade; Agência dos Direitos Fundamentais, em Viena); Nações Unidas (Comité para a Eliminação da Discriminação Racial).\nFontes: Lei n.º 3/2024, de 15 de janeiro; sítios dos organismos; Lusa/RTP, 2025 e 2026.",
 "s-con-jogo": "10 minutos. Seis situações, três portas. Pode ser respondido no telemóvel. Lembrar que apresentar queixa a estes organismos é gratuito e não impede de ir a tribunal.",
 "s-con-direitos": "15 minutos. Critério de evidência do DR3: relacionar direitos políticos e associativos. A relação: os direitos associativos dão força aos políticos. Os sindicatos e as confederações patronais que se sentam à mesa da concertação são associações; as associações de imigrantes e de moradores são ouvidas pelas câmaras e pelo Estado.\nConstituição: artigo 46.º (liberdade de associação), 48.º (participação na vida pública), 49.º (direito de sufrágio), 51.º (associações e partidos políticos), 52.º (direito de petição e de ação popular), 55.º (liberdade sindical).\nEstrangeiros: direitos associativos e sindicais iguais. Direito de voto: nas autárquicas, cidadãos de Estados da União Europeia e de países com reciprocidade (por exemplo, Brasil e Cabo Verde, com tempo mínimo de residência), mediante recenseamento voluntário; os brasileiros com estatuto de igualdade de direitos políticos votam também nas legislativas. A lista de países é publicada antes de cada eleição: confirmar no portal gov.pt («Votar em eleições portuguesas») ou na Comissão Nacional de Eleições.\nFechar com exemplos da turma: clube, associação de pais, sindicato, coletividade, bombeiros voluntários.",
 "s-con-simula": "25 minutos. Três grupos (com turmas pequenas, dois ou três formandos por lado). 5 minutos de preparação em separado, 10 de negociação à mesa (juntar três mesas em triângulo), 5 para escrever o acordo e 5 de balanço.\nBalanço: quem cedeu em quê? O acordo é melhor ou pior do que cada lado queria? Foi mais fácil para quem veio com uma proposta concreta? É a experiência direta da concertação: ninguém ganha tudo.\nO tema é um pretexto; pode ser trocado por outro mais próximo da turma (trabalho ao domingo, teletrabalho, idade da reforma). Em Portugal houve um projeto-piloto voluntário da semana de quatro dias em 2023, em empresas privadas.\nEnvio do acordo pelo telemóvel (atividade «concertacao»).",
 "s-para-que-8": "Fecho do bloco (5 minutos).",
 "s-mig-caso": "Abertura (10 minutos). Quatro frases que se ouvem; votar e só depois ver os dados. Critério de evidência do DR3: situar-se face à inclusão da população migrante, o que pede factos antes de opiniões.\nDados de 2025 (Segurança Social; relatório do Observatório das Migrações, março de 2026): contribuições de estrangeiros, cerca de 4 149 milhões de euros (14% do total); prestações pagas a estrangeiros, cerca de 822 milhões; 1 115 541 contribuintes estrangeiros, cerca de 20% do total.\nRigor e equilíbrio: esta diferença compara só o que entrou e saiu no ano. Não conta as pensões que estes trabalhadores virão a receber, nem a despesa com saúde, escola ou habitação, nem os impostos que pagam. O próprio responsável da Segurança Social avisou que não se deve falar em «saldo» sem esta ressalva. Os números respondem a uma frase concreta («recebem mais do que descontam»), não encerram o debate sobre a imigração.\nTurma com formandos imigrantes: tratar o tema com dados e sem pedir testemunhos; quem quiser, partilha.",
 "s-mig-impactos": "15 minutos. Conteúdo do programa: impactos económicos, culturais e sociais dos fluxos migratórios no Portugal contemporâneo. Três colunas, cada uma com efeitos positivos e dificuldades: o objetivo é avaliar, não fazer propaganda num sentido ou noutro.\nNúmero de abertura: 1 597 530 estrangeiros residentes no fim de 2025 (Instituto Nacional de Estatística), cerca de 14% da população. Setor com mais contribuintes estrangeiros: restauração e alojamento.\nNão esquecer a emigração: Portugal continua a ser também um país de partida (dezenas de milhares de saídas por ano, segundo o Observatório da Emigração). A pergunta final põe a turma do lado de quem parte: remessas e experiência, mas aldeias sem gente e famílias separadas.\nLigar à unidade de Cultura, Língua e Comunicação 6 (DR4, mobilidades), se a turma a frequenta.",
 "s-mig-unidade": "10 minutos. Conceitos-chave do DR3: condição humana; unidade e diversidade. No início as peças estão espalhadas e tortas; no segundo clique arrumam-se numa grelha: partilham uma ordem comum sem deixarem de ser diferentes.\nCondição humana: expressão de Hannah Arendt («A Condição Humana», 1958). Aqui basta a ideia simples: antes de sermos portugueses ou estrangeiros, novos ou velhos, somos seres que nascem, dependem uns dos outros e precisam de um lugar. É o fundamento da dignidade igual (Constituição, artigos 1.º e 13.º).\nRetoma o slide «Da tolerância à unidade na diversidade» do bloco DR1.5. Discussão: onde passa a linha entre o que tem de ser comum (a lei, os direitos das mulheres e das crianças, a língua para trabalhar) e o que pode ser diferente (religião, comida, vestuário)? Não há consenso em todos os pontos: é esse o debate público.",
 "s-mig-cidadania": "10 minutos. Conteúdo do programa: a educação para a cidadania e a preservação da unidade na diversidade. Três passos (conhecer, respeitar, participar) e quatro lugares onde se aprende.\nA ligação à unidade na diversidade: a educação para a cidadania é o que permite que pessoas muito diferentes partilhem as mesmas regras, porque as conhecem e ajudaram a fazê-las.\nNa escola existe a área de Cidadania e Desenvolvimento (Estratégia Nacional de Educação para a Cidadania, de 2017, revista em 2025: se a turma perguntar pelos conteúdos atuais, confirmar no sítio da Direção-Geral da Educação). Esta própria disciplina é educação para a cidadania de adultos: vale a pena dizê-lo.",
 "s-mig-situar": "20 minutos. Critério de evidência do DR3: situar-se face à inclusão da população migrante. Cada formando escolhe no telemóvel (atividade «incluir») o que considera mais importante e escreve um argumento com a estrutura do cartão; depois, em pares, ouve um colega com outra escolha e resume a posição dele antes de responder.\nNão há resposta certa, e a tua opinião não entra: o que se avalia é a fundamentação (um facto ou um exemplo; reconhecer a posição contrária). As regras do grupo combinadas no início da unidade aplicam-se aqui: critica-se a ideia, não a pessoa.\nA última opção («conhecer e cumprir as regras do país») lembra que a inclusão tem dois lados: o que a sociedade oferece e o que pede a quem chega.",
 "s-para-que-9": "Fecho do bloco e do DR3 (5 minutos).",
 "s-jogo7": "Jogo de revisão do DR3: 8 perguntas, 20 segundos cada.",
 "s-tel-inclusao": "O mesmo jogo no telemóvel, seguido de três perguntas escritas (atividade «inclusao»).",
 "s-dr4": "Abertura do DR4 (contexto macroestrutural). O último círculo: do Estado para cima. O papel da multiculturalidade e da diversidade na construção de uma identidade europeia.",
 "s-eu-caso": "Abertura (10 minutos). Seis decisões do dia a dia; pode ser respondido no telemóvel. A ideia: há decisões que já não são tomadas só em Lisboa, e outras que continuam a ser.\nFactos: carregador comum (Diretiva (UE) 2022/2380, aplicável a telemóveis desde 28 de dezembro de 2024); fim das tarifas de itinerância em junho de 2017; taxas de juro de referência fixadas pelo Banco Central Europeu para a zona euro (21 países desde 1 de janeiro de 2026, com a entrada da Bulgária).",
 "s-eu-supra": "15 minutos. Conteúdo do programa: dimensão supranacional dos poderes do Estado. No primeiro clique, as caixas «moeda» e «comércio» de cada Estado sobem para a caixa comum: são poderes que os Estados decidiram exercer em conjunto. As outras ficam em baixo (com regras comuns em alguns pontos, mas decididas em cada país).\nSupranacional: as decisões tomadas em comum (muitas por maioria) obrigam todos, mesmo quem votou contra, e o direito da União aplica-se diretamente em Portugal (Constituição, artigo 8.º, n.º 4). Intergovernamental: cada Estado mantém a última palavra, como na Organização das Nações Unidas ou na política externa europeia, onde se exige unanimidade.\nÉ uma simplificação: na realidade há competências exclusivas da União (união aduaneira, concorrência, política monetária do euro, política comercial, pescas), partilhadas (ambiente, transportes, agricultura) e de apoio (saúde, educação, cultura). Fonte: Tratado sobre o Funcionamento da União Europeia, artigos 3.º a 6.º.\nA pergunta final é um debate em aberto (soberania partilhada ou perdida): apresentar os dois lados. Importa do teu site de Área de Integração (cidadania europeia, aulas 5 e 8) o que precisares.",
 "s-eu-documentos": "15 minutos. Conteúdo do programa: exploração de documentos estruturantes da construção europeia. Seis documentos, um por clique, cada um com uma frase.\nDatas: Declaração Schuman, 9 de maio de 1950 (por isso 9 de maio é o Dia da Europa); Tratado de Roma, assinado em 1957 pelos seis fundadores (França, Alemanha Ocidental, Itália, Bélgica, Países Baixos, Luxemburgo); Ato Único Europeu, assinado em 1986, ano da adesão de Portugal e de Espanha (1 de janeiro); Tratado de Maastricht, assinado em 1992, em vigor em 1993; Carta dos Direitos Fundamentais, proclamada em 2000; Tratado de Lisboa, assinado em 13 de dezembro de 2007 no Mosteiro dos Jerónimos, em vigor desde 1 de dezembro de 2009.\nFonte: EUR-Lex e sítio oficial da União Europeia (european-union.europa.eu). No teu site de Área de Integração (cidadania europeia, aulas 2 a 4) há mais pormenor e animações.",
 "s-eu-ler": "15 minutos, em pares, numa folha. Ler um texto jurídico curto e ligá-lo à vida. O texto do slide é uma paráfrase fiel do artigo 2.º do Tratado da União Europeia; o texto oficial, em português, está no EUR-Lex (pode ser projetado).\nResposta à terceira pergunta: «unidade na diversidade» (bloco DR1.5 e bloco DR3.2). O lema europeu «Unida na diversidade» é usado desde 2000.\nCritério de evidência do DR4: expressar e demonstrar respeito e solidariedade pelas diferentes identidades culturais. Os valores do tratado são os mesmos da Constituição portuguesa (artigos 1.º, 2.º e 13.º): vale a pena mostrar a continuidade.",
 "s-eu-juridico": "15 minutos. Conteúdo do programa: relações jurídicas a um nível macro (agentes de nível governamental e sociedade civil). Critério de evidência do DR4: discutir e avaliar o papel dos cidadãos no mundo atual, as relações jurídicas no marco de integração supranacional e a dimensão supranacional dos poderes do Estado face aos cidadãos.\nDois tipos de agentes: os governamentais (Estados e organizações criadas por eles) e a sociedade civil (tudo o que não é Estado nem mercado em sentido estrito: associações, sindicatos, organizações não governamentais; aqui incluímos também as empresas e os cidadãos).\nQuatro instrumentos ao alcance de qualquer cidadão europeu: petição ao Parlamento Europeu; queixa ao Provedor de Justiça Europeu (má administração das instituições europeias); iniciativa de cidadania europeia (um milhão de assinaturas de pelo menos sete Estados-Membros obriga a Comissão a responder); queixa ao Tribunal Europeu dos Direitos Humanos, em Estrasburgo, que é do Conselho da Europa e não da União, depois de esgotados os recursos internos.\nLigar ao DR3: é a mesma lógica dos direitos políticos e associativos, uma escala acima.",
 "s-eu-identidade": "15 minutos. Fecha o percurso da unidade: os círculos de identidade crescem do eu até à humanidade, um por clique. Ninguém tem de escolher um só círculo: é a ideia de identidade social do bloco DR1.4 («ninguém é uma coisa só»).\nCidadania europeia (desde Maastricht; hoje no artigo 20.º do Tratado sobre o Funcionamento da União Europeia): acresce à nacional e não a substitui. Direitos: circular e residir; votar e ser eleito nas eleições autárquicas e europeias no país de residência; proteção diplomática e consular de qualquer Estado-Membro; petição e queixa.\nIdentidade «em construção» e o papel da multiculturalidade: a União tem 24 línguas oficiais e nenhuma cultura única; o que une são valores e regras (slide anterior). Há quem conteste que exista uma identidade europeia: a pergunta do navio de Teseu (bloco DR1.2) serve para discutir isso sem dar a resposta.",
 "s-para-que-10": "Fecho do bloco (5 minutos). «Metade das regras» é uma imagem, não uma estatística: uma parte grande da legislação económica e ambiental tem origem europeia.",
 "s-pat-caso": "Abertura (10 minutos). Cinco casos, duas respostas. A distinção que o jogo prepara: há espaços que não pertencem a nenhum Estado (a Lua, os fundos marinhos internacionais, a Antártida) e há bens que pertencem a um país, mas que a humanidade reconhece como seus e que esse país se compromete a proteger (Património Mundial).\nFontes: Tratado do Espaço Exterior (1967), artigo II; Convenção das Nações Unidas sobre o Direito do Mar (1982), artigo 136.º; Tratado da Antártida (1959); listas da UNESCO (Organização das Nações Unidas para a Educação, a Ciência e a Cultura).",
 "s-pat-conceito": "15 minutos. Conteúdo do programa: exploração do conceito de Património Comum da Humanidade. Competência do DR4: relacionar património comum da humanidade com interdependência e solidariedade.\nTrês famílias, uma por clique. Rigor: em sentido jurídico estrito, «património comum da humanidade» designa os espaços que nenhum Estado pode apropriar (fundos marinhos internacionais, Lua). O Património Mundial da UNESCO é outra figura: os bens continuam sob a soberania do país, que se obriga perante os outros a protegê-los. Na linguagem corrente usa-se a mesma expressão para os dois.\nPortugal: 17 bens na Lista do Património Mundial; os primeiros, de 1983, foram o Mosteiro dos Jerónimos e a Torre de Belém, o Mosteiro da Batalha, o Convento de Cristo e o centro de Angra do Heroísmo; os mais recentes, de 2019, o Real Edifício de Mafra e o Santuário do Bom Jesus do Monte. Confirmar o número em whc.unesco.org se houver novas inscrições.\nInterdependência: o que acontece ao fundo do mar, ao clima ou a um monumento afeta gente de outros países e de outras gerações. É por isso que precisa de regras comuns.",
 "s-pat-implica": "15 minutos. Critério de evidência do DR4: refletir sobre as implicações sociais do património comum da humanidade. Quatro implicações, com o lado bom e o lado difícil.\nPressão turística: ligar à gentrificação e à turistificação (se a turma frequenta Cultura, Língua e Comunicação 6, já viram «uma rua no tempo»).\nCaso de Tombuctu: em 2016 o Tribunal Penal Internacional condenou Ahmad Al Faqi Al Mahdi a nove anos de prisão pela destruição intencional de mausoléus e de uma mesquita em Tombuctu (Mali), em 2012. Foi a primeira condenação deste tribunal apenas por destruição de património cultural.\nInterdependência: conceito da competência do DR4, a par da solidariedade (slide seguinte).",
 "s-pat-respeito": "15 minutos. Conteúdo do programa: respeito e solidariedade entre identidades culturais distintas. Critério de evidência do DR4: expressar e demonstrar respeito e solidariedade pelas diferentes identidades culturais.\nA escada retoma e prolonga a do bloco DR1.5 (tolerância, aceitação, unidade na diversidade): agora à escala do mundo, e com um degrau acima do respeito, a solidariedade (agir quando o outro é atingido).\nA Declaração Universal sobre a Diversidade Cultural (UNESCO, 2 de novembro de 2001), artigo 1.º, afirma que a diversidade cultural é património comum da humanidade. É a ponte entre os dois temas do bloco: o património não são só pedras, são também as culturas vivas.\nCidadania mundial (conceito-chave do DR4): não é um estatuto jurídico, como a cidadania portuguesa ou a europeia; é uma atitude de responsabilidade.",
 "s-pat-pesquisa": "15 minutos, em pares. O código QR abre a página de Portugal no Centro do Património Mundial da UNESCO (em inglês; o telemóvel traduz). Cada par escolhe um bem e responde a quatro perguntas; envio pelo telemóvel (atividade «patrimonio»).\nOs formandos de outros países podem escolher um bem do seu país de origem: reforça a ideia de património comum.",
 "s-para-que-11": "Fecho do bloco e do DR4 (5 minutos).",
 "s-jogo8": "Jogo de revisão do DR4: 8 perguntas, 20 segundos cada.",
 "s-tel-europa": "O mesmo jogo no telemóvel, seguido de três perguntas escritas (atividade «europa»).",
 "s-of1": "Projeto · oficina do DR1. Oficina do projeto de grupo (100 minutos): recordar o DR com o filtro do índice, 10 minutos; escolher o que entra e distribuir tarefas, 15; construir os slides, 45; mostrar a outro grupo, 15; ponto da situação no telemóvel, 15.",
 "s-of1-pede": "Os três critérios de evidência do DR1 (Referencial de Competências-Chave, Cidadania e Profissionalidade 4, núcleo gerador Identidade e Alteridade), em linguagem simples. Cada clique mostra um; os grupos assinalam os que o trabalho já cumpre. À direita, ideias para os três slides mínimos. Mostrar o filtro «DR1» do índice: lista todos os slides que mobilizam este domínio, mesmo os de outros blocos. Temporizador de 45 minutos. No fim, atividade «proj1».",
 "s-d1-apresentacao": "Era a apresentação oral individual de três minutos no fecho do DR1. Passa a ser o guião da parte do DR1 do trabalho de grupo: escolher um tema do DR1, ligá-lo a um caso do grupo e mostrar uma atividade feita nas aulas. A mesma estrutura (o que é, um exemplo nosso, para que nos serve) serve para os outros três DR.",
 "s-of2": "Projeto · oficina do DR2. Oficina do projeto de grupo (100 minutos): recordar o DR com o filtro do índice, 10 minutos; escolher o que entra e distribuir tarefas, 15; construir os slides, 45; mostrar a outro grupo, 15; ponto da situação no telemóvel, 15.",
 "s-of2-pede": "Os três critérios de evidência do DR2 (Referencial de Competências-Chave, Cidadania e Profissionalidade 4, núcleo gerador Identidade e Alteridade), em linguagem simples. Cada clique mostra um; os grupos assinalam os que o trabalho já cumpre. À direita, ideias para os três slides mínimos. Mostrar o filtro «DR2» do índice: lista todos os slides que mobilizam este domínio, mesmo os de outros blocos. Temporizador de 45 minutos. No fim, atividade «proj2».",
 "s-of3": "Projeto · oficina do DR3. Oficina do projeto de grupo (100 minutos): recordar o DR com o filtro do índice, 10 minutos; escolher o que entra e distribuir tarefas, 15; construir os slides, 45; mostrar a outro grupo, 15; ponto da situação no telemóvel, 15.",
 "s-of3-pede": "Os três critérios de evidência do DR3 (Referencial de Competências-Chave, Cidadania e Profissionalidade 4, núcleo gerador Identidade e Alteridade), em linguagem simples. Cada clique mostra um; os grupos assinalam os que o trabalho já cumpre. À direita, ideias para os três slides mínimos. Mostrar o filtro «DR3» do índice: lista todos os slides que mobilizam este domínio, mesmo os de outros blocos. Temporizador de 45 minutos. No fim, atividade «proj3».",
 "s-of4": "Projeto · oficina do DR4. Oficina do projeto de grupo (100 minutos): recordar o DR com o filtro do índice, 10 minutos; escolher o que entra e distribuir tarefas, 15; construir os slides, 45; mostrar a outro grupo, 15; ponto da situação no telemóvel, 15.",
 "s-of4-pede": "Os três critérios de evidência do DR4 (Referencial de Competências-Chave, Cidadania e Profissionalidade 4, núcleo gerador Identidade e Alteridade), em linguagem simples. Cada clique mostra um; os grupos assinalam os que o trabalho já cumpre. À direita, ideias para os três slides mínimos. Mostrar o filtro «DR4» do índice: lista todos os slides que mobilizam este domínio, mesmo os de outros blocos. Temporizador de 45 minutos. No fim, atividade «proj4».",
 "s-final": "Apresentações finais dos grupos: 15 minutos cada, os quatro DR num só trabalho. Sortear a ordem no início.",
 "s-final-avaliar": "Durante cada apresentação, os outros grupos avaliam no telemóvel (atividade «pares»); o formador usa a mesma grelha. Temporizador de 15 minutos. As avaliações dos colegas são formativas: tu decides o peso que têm.",
 "s-final-fecho": "Fecho da unidade. Recapitular os quatro DR, do eu ao mundo, e voltar à primeira atividade (a história do meu nome). Autoavaliação final no telemóvel (atividade «fecho»).",
 "s-esc-racismo": "Oficina de escrita a partir do manual da Areal (temas 5 e 13). O texto do discurso tem direitos de autor: ouvir a gravação (há versões legendadas) em vez de distribuir a transcrição completa. Os textos chegam à folha «Avaliação contínua», separador «CP 4 · Texto: o sonho de Luther King» (atividade «esc-racismo»).",
 "s-esc-genero": "Temas 6 e 7 do manual. Datas: decreto de 1931 (voto das mulheres com curso secundário ou superior); Decreto-Lei n.º 49 317, de 1969 (saída do país sem autorização do marido); Constituição de 1976. Dado a atualizar todos os anos: barómetro do Gabinete de Estratégia e Planeamento (12,5% na remuneração base em 2023). Atividade «esc-genero».",
 "s-esc-sigilo": "Tema 11 do manual. O caso da Marta é inventado. Pode ser feito em pares antes de escrever: um faz de vizinha, o outro de Marta. Atividade «esc-sigilo».",
 "s-esc-migracoes": "Temas 14 a 17 do manual. Cuidado com histórias pessoais difíceis: quem não quiser contar a sua pode contar a de outra pessoa. O número de estrangeiros residentes é o mesmo do bloco DR3.2 (atualizar em conjunto). Atividade «esc-migracoes».",
 "s-esc-valores": "Tema 19 do manual; responde ao ponto «por reforçar» da planificação (democracia e justiça sem slide de definição). Atividade «esc-valores».",
 "s-esc-schengen": "Tema 24 do manual. Dados do Conselho da União Europeia: 29 países; Bulgária e Roménia desde 1 de janeiro de 2025; Chipre em avaliação. Confirmar antes de cada edição. Atividade «esc-schengen».",
 "s-esc-patrimonio": "Temas 20 a 23 do manual. Liga à pesquisa «um património perto de ti» do slide anterior: o bem pesquisado pode ser o da candidatura. Atividade «esc-patrimonio».",
 "s-esc-final": "Tema 25 do manual (atividade aglutinadora). Texto individual, para avaliação sumativa a par do trabalho de grupo. Pode ser escrito em casa. Atividade «esc-final».",
};
